allowed=set(w.lower() for w in allowed_text.split())
out=[]
for i,line in enumerate(lines,1):
    text=re.sub(r'<[^>]+>',' ',line)
    toks=re.findall(r"[A-Za-z][A-Za-z'\-]*", text)
    flagged=[t for t in toks if t.lower() not in allowed and len(t)>=4]
    if flagged:
        out.append((i, sorted(set(flagged)), line.strip()[:260]))
from collections import Counter
wc=Counter()
for i,fl,line in out:
    for w in fl: wc[w]+=1
print("FLAGGED WORD TYPES:", len(wc))
for w,n in sorted(wc.items(), key=lambda x:-x[1])[:200]:
    print(f"{n:4} {w}")
